import os
import sys


def ls(args):
    """RTK's compact listing: recursively list directory names, then files."""
    paths = [x for x in args if not x.startswith('-')]
    roots = paths or ['.']
    ultra = False
    recursive = '-R' in args or '--recursive' in args
    try:
        dirs, names = [], []
        direct_files = [(p, p) for p in roots if not os.path.isdir(p)]
        for root in roots:
            if not os.path.isdir(root):
                continue
            for base, ds, fs in os.walk(root):
                if not recursive and base != root:
                    ds[:] = []
                    continue
                ds.sort()
                fs.sort()
                relbase = os.path.relpath(base, root)
                for d in ds:
                    rel = os.path.join(relbase, d) if relbase != '.' else d
                    dirs.append(os.path.basename(rel))
                if recursive or base == root:
                    for f in fs:
                        rel = os.path.join(relbase, f) if relbase != '.' else f
                        names.append((f, os.path.join(root, rel)))
        names = direct_files + names
        for d in dirs:
            print(d if ultra else d + '/')
        for f, rel in names:
            try:
                size = os.path.getsize(rel)
            except OSError:
                size = 0
            print(f if ultra else f'{f}  {_size(size)}')
        return 0
    except OSError as e:
        print(f'rtk: {e}', file=sys.stderr)
        return 1


def _size(n):
    if n < 1024: return f'{n}B'
    if n < 1024**2: return f'{n/1024:.1f}K'
    if n < 1024**3: return f'{n/1024**2:.1f}M'
    return f'{n/1024**3:.1f}G'


def smart(args):
    filename = next((x for x in args if not x.startswith('-')), None)
    if not filename:
        print('error: the following required argument was not provided: <FILE>', file=sys.stderr)
        return 2
    try:
        with open(filename, encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except OSError as e:
        print(f'rtk: Failed to read file: {filename} ({e})', file=sys.stderr)
        return 1
    ext = os.path.splitext(filename)[1].lower()
    lang = {'.py':'Python','.pyi':'Python','.rs':'Rust','.js':'JavaScript','.jsx':'JavaScript','.ts':'TypeScript','.tsx':'TypeScript','.go':'Go','.c':'C','.h':'C','.cpp':'C++','.java':'Java','.rb':'Ruby','.sh':'Shell','.md':'Data','.json':'Data','.toml':'Data','.yaml':'Data','.yml':'Data'}.get(ext, 'Code')
    count = len(lines)
    print(f'{lang} code ({count} lines)')
    print('General purpose code file')
    return 0


def tree(args):
    print('rtk: tree command not found. Install it first:', file=sys.stderr)
    print('- macOS: brew install tree\n- Ubuntu/Debian: sudo apt install tree\n- Fedora/RHEL: sudo dnf install tree\n- Arch: sudo pacman -S tree', file=sys.stderr)
    return 1
