import json


def _kind(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, (int, float)):
        return "int" if isinstance(v, int) else "float"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "array"
    return "object"


def render(data, depth=5, keys_only=False):
    def scalar(v):
        if keys_only:
            return _kind(v)
        if isinstance(v, str):
            return '"' + v + '"'
        return json.dumps(v, ensure_ascii=False, separators=(",", ": "))

    def value(v, level, indent, in_array=False):
        pad = " " * indent
        if isinstance(v, dict):
            if level > depth:
                return pad + "..."
            if not v:
                return pad + "{}"
            lines = [pad + "{"]
            keys = sorted(v, key=lambda x: str(x))
            for i, key in enumerate(keys):
                item = v[key]
                kp = " " * (indent + 2)
                k = str(key)
                if isinstance(item, (dict, list)):
                    lines.append(f"{kp}{k}:")
                    lines.append(value(item, level + 1, indent + 2))
                else:
                    lines.append(f"{kp}{k}: {scalar(item)}" + ("," if keys_only and i + 1 < len(keys) else ""))
            lines.append(pad + "}")
            return "\n".join(lines)
        if isinstance(v, list):
            if level > depth:
                return pad + "..."
            if not v:
                return pad + "[]"
            if keys_only:
                if len(v) == 1:
                    item = value(v[0], level + 1, indent + 2)
                    return pad + "[\n" + item + "\n" + pad + "]"
                first = _kind(v[0])
                if level + 1 > depth:
                    if first == "null":
                        elems = [" " * (indent + 2) + "..." for _ in v]
                        return pad + "[\n" + "\n".join(elems) + f"\n{pad}]"
                    return f"{pad}[...] ({len(v)})"
                if first in ("int", "float", "bool", "string"):
                    return f"{pad}[{first}] ({len(v)})"
                if first == "null":
                    elems = [" " * (indent + 2) + scalar(x) for x in v]
                    return pad + "[\n" + "\n".join(elems) + f"\n{pad}]"
                if first == "array" and all(not isinstance(x, (dict, list)) for x in v[0]):
                    inner = v[0]
                    elems = [" " * (indent + 4) + _kind(x) for x in inner]
                    return pad + "[[\n" + "\n".join(elems) + f"\n{' ' * (indent + 2)}]] ({len(v)})"
                shaped = value(v[0], level + 1, indent + 2).splitlines()
                if shaped:
                    lines = [pad + "[" + shaped[0].lstrip()]
                    lines.extend(shaped[1:-1])
                    lines.append(shaped[-1] + f"] ({len(v)})")
                    return "\n".join(lines)
                return f"{pad}[] ({len(v)})"
            # Keep arrays of primitive values inline when nested in a container.
            if level > 0 and level + 1 <= depth and all(not isinstance(x, (dict, list)) for x in v):
                return pad + "[" + ", ".join(scalar(x) for x in v) + "]"
            if level > depth and v:
                return pad + "..."
            if level + 1 > depth and all(not isinstance(x, (dict, list)) for x in v):
                return pad + "[" + ", ".join("..." for _ in v) + "]"
            lines = [pad + "["]
            for x in v:
                lines.append(value(x, level + 1, indent + 2, True) + ",")
            lines.append(pad + "]")
            return "\n".join(lines)
        if level > depth:
            return pad + "..."
        return pad + scalar(v)

    return value(data, 0, 0)
