        root = args[1] if len(args) > 1 and not args[1].startswith('-') else '.'
        args = [root, '-name', pattern] + args[2:]
    elif not args:
        args = ['.']
    elif args[0].startswith('-'):
        # Native find treats the first predicate as an expression when no
        # starting path is supplied; RTK supplies the current directory.
        args = ['.'] + args
    try:
        p = subprocess.run(['find'] + args, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except OSError as e:
        print(f'rtk: {e}', file=sys.stderr)
        return 1
    if p.returncode:
        if p.stderr:
            sys.stderr.write(p.stderr)
        return p.returncode
    paths = [x for x in p.stdout.splitlines() if x]
    if not paths:
        pat = pattern
        if pat is None:
            for i, x in enumerate(args[:-1]):
                if x in ('-name', '-iname', '-path', '-ipath'):
                    pat = args[i + 1]
                    break
        if pat is None:
            pat = args[0] if args else '.'
        print(f"0 for '{pat}'")
        return 0

    start_root = args[0] if args and not args[0].startswith('-') else '.'
    dirs = set()
    files_by_dir = {}
    direct_dirs = set()
    for result in paths:
        path = result.rstrip('/') or '.'
        try:
            path = os.path.relpath(path, start_root)
        except ValueError:
            pass
        if path == '..' or path.startswith('..' + os.sep):
            path = result.rstrip('/') or '.'
        if os.path.isdir(path):
            direct_dirs.add(path)
        else:
            parent = os.path.dirname(path) or '.'
            dirs.add(parent)
            files_by_dir.setdefault(parent, []).append(os.path.basename(path))
    dirs.update(direct_dirs)
    for d in list(dirs):
        parent = os.path.dirname(d.rstrip('/'))
        if parent and parent != d:
            # Include ancestors needed to render a compact tree.
            while parent and parent != '.':
                dirs.add(parent)
                next_parent = os.path.dirname(parent)
                if next_parent == parent:
                    break
                parent = next_parent
            dirs.add('.')
    if not dirs:
        dirs.add('.')
    dirs = sorted(dirs, key=lambda x: (x.count(os.sep), x))
    files_count = sum(len(v) for v in files_by_dir.values())
    # Summary counts directories containing matched files, not ancestor rows
    # synthesized for the compact tree display.
    dirs_count = len(set(files_by_dir))
    if not files_count and direct_dirs:
        # The native tree formatter represents the starting directory as D
        # and its matched child directories as entries in that row.
        files_count = max(0, len(direct_dirs) - 1)
        dirs_count = 1
    print(f'{files_count}F {dirs_count}D:\n')
    for d in dirs:
        label = './' if d in ('.', '') else os.path.normpath(d).rstrip('/') + '/'
        children = sorted(os.path.basename(x.rstrip('/')) for x in direct_dirs
                          if x != d and (os.path.dirname(x.rstrip('/')) or '.') == d
                          and x not in files_by_dir)
        names = sorted(files_by_dir.get(d, []))
        items = children + names
        if items:
            print(label + ' ' + ' '.join(items))
    if files_count:
        exts = {}
        for values in files_by_dir.values():
            for name in values:
                ext = os.path.splitext(name)[1]
                if ext:
                    exts[ext] = exts.get(ext, 0) + 1
        if exts:
            print('\next: ' + ' '.join(f'{e}({n})' for e, n in sorted(exts.items(), key=lambda item: -item[1])))
    return 0
