import os
import re
import sys


def ls(args):
    """RTK's compact listing: recursively list directory names, then files."""
    paths = [x for x in args if not x.startswith('-')]
    roots = paths or ['.']
    ultra = False
    recursive = '-R' in args or '--recursive' in args
    list_dirs = '-d' in args or '--directory' in args
    ignored = {'.git', '__pycache__', 'node_modules', 'target', '.cache'}
    if list_dirs and not paths:
        print('(empty)')
        return 0
    try:
        dirs, names = [], []
        direct_files = [(p, p) for p in roots if not os.path.isdir(p)]
        if list_dirs:
            dirs = [os.path.normpath(p) for p in roots if os.path.isdir(p)]
        for root in ([] if list_dirs else roots):
            if not os.path.isdir(root):
                continue
            for base, ds, fs in os.walk(root):
                if not recursive and base != root:
                    ds[:] = []
                    continue
                ds.sort()
                fs.sort()
                relbase = os.path.relpath(base, root)
                for d in ds:
                    rel = os.path.join(relbase, d) if relbase != '.' else d
                    if not (relbase == '.' and d in ignored):
                        dirs.append(os.path.basename(rel))
                if recursive or base == root:
                    for f in fs:
                        rel = os.path.join(relbase, f) if relbase != '.' else f
                        names.append((f, os.path.join(root, rel)))
        names = direct_files + names
        for d in dirs:
            print(d if ultra else d + '/')
        for f, rel in names:
            try:
                size = os.path.getsize(rel)
            except OSError:
                size = 0
            print(f if ultra else f'{f}  {_size(size)}')
        return 0
    except OSError as e:
        print(f'rtk: {e}', file=sys.stderr)
        return 1


def _size(n):
    if n < 1024: return f'{n}B'
    if n < 1024**2: return f'{n/1024:.1f}K'
    if n < 1024**3: return f'{n/1024**2:.1f}M'
    return f'{n/1024**3:.1f}G'


def smart(args):
    filename = None
    skip = False
    for arg in args:
        if skip:
            skip = False
            continue
        if arg == '--model':
            skip = True
        elif arg in ('--force-download',):
            continue
        elif not arg.startswith('-'):
            filename = arg
            break
    if not filename:
        print('error: the following required argument was not provided: <FILE>', file=sys.stderr)
        return 2
    try:
        with open(filename, encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except OSError as e:
        print(f'rtk: Failed to read file: {filename}: {e.strerror} (os error {e.errno})', file=sys.stderr)
        return 1
    ext = os.path.splitext(filename)[1].lower()
    lang = {'.py':'Python','.pyi':'Python','.rs':'Rust','.js':'JavaScript','.jsx':'JavaScript','.ts':'TypeScript','.tsx':'TypeScript','.go':'Go','.c':'C','.h':'C','.cpp':'C++','.java':'Java','.rb':'Ruby','.sh':'Shell','.md':'Data','.txt':'Data','.json':'Data','.toml':'Data','.yaml':'Data','.yml':'Data'}.get(ext, 'Code')
    count = len(lines)
    src = ''.join(lines)
    funcs = []
    structs = []
    if lang == 'Python':
        funcs = re.findall(r'^\s*(?:async\s+)?def\s+(\w+)', src, re.M)
        structs = re.findall(r'^\s*class\s+(\w+)', src, re.M)
    elif lang in ('JavaScript', 'TypeScript'):
        funcs = re.findall(r'^\s*function\s+(\w+)|^\s*(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s*)?\([^)]*\)\s*=>', src, re.M)
        funcs = [a or b for a, b in funcs]
    elif lang == 'Rust':
        funcs = re.findall(r'^\s*(?:pub(?:\([^)]*\))?\s+)?fn\s+(\w+)', src, re.M)
        structs = re.findall(r'^\s*(?:pub\s+)?struct\s+(\w+)', src, re.M)
    elif lang == 'Go':
        structs = re.findall(r'^\s*type\s+(\w+)\s+struct\b', src, re.M)
    if funcs and structs:
        print(f'{lang} module ({len(funcs)} fn, {len(structs)} struct) - {count} lines')
        if lang == 'Python':
            print('defines: ' + ', '.join(funcs[:5]))
        elif lang == 'Rust':
            methods = re.findall(r'\bfn\s+(\w+)', src)
            nonmodule = [n for n in methods if n not in funcs]
            print('defines: ' + ', '.join(nonmodule[:5]))
        else:
            print('General purpose code file')
        return 0
    if funcs:
        print(f'{lang} functions ({len(funcs)} fn) - {count} lines')
        print('defines: ' + ', '.join(funcs[:5]))
        return 0
    if structs:
        print(f'{lang} data structures ({len(structs)} struct) - {count} lines')
        print('General purpose code file')
        return 0
    print(f'{lang} code ({count} lines)')
    print('General purpose code file')
    return 0


def tree(args):
    print('rtk: tree command not found. Install it first:', file=sys.stderr)
    print('- macOS: brew install tree\n- Ubuntu/Debian: sudo apt install tree\n- Fedora/RHEL: sudo dnf install tree\n- Arch: sudo pacman -S tree', file=sys.stderr)
    return 1
